import { createHash } from 'crypto';
import type { GuidanceDocument } from '../../types/guidance';

export const guidanceSourceDigest = (document: GuidanceDocument): string =>
  createHash('sha256')
    .update(
      JSON.stringify({
        markdown: document.markdown,
        ...(document.origin ? { source: document.origin.source } : {}),
        attachments: (document.attachments ?? []).map(
          ({ source, alt, title, hash }) => ({ source, alt, title, hash }),
        ),
        references: (document.references ?? []).map((reference) => {
          if (reference.kind === 'directory')
            return {
              kind: reference.kind,
              path: reference.path,
              intent: reference.intent,
            };
          return {
            kind: reference.kind,
            url: reference.url,
            intent: reference.intent,
            revision: reference.revision,
            files: (reference.files ?? []).map(({ name, content }) => ({
              name,
              content,
            })),
          };
        }),
      }),
    )
    .digest('hex');
